        [Fact]
        public async Task InitializeAsync_ShouldLoadMetricsFromRepositoriesAndServices()
        {
            // Arrange
            var mockCatRepo = new Mock<ICategoryRepository>();
            var mockRuleRepo = new Mock<IRuleRepository>();
            var mockShadowService = new Mock<IShadowModeService>();

            mockCatRepo.Setup(r => r.GetAllAsync(false))
                .ReturnsAsync(new List<CategoryNode>
                {
                    new CategoryNode("Cat1"),
                    new CategoryNode("Cat2"),
                    new CategoryNode("Cat3")
                });

            mockRuleRepo.Setup(r => r.GetAllDictionaryRulesAsync())
                .ReturnsAsync(new List<DictionaryRule>
                {
                    new DictionaryRule(new CategoryNode("Cat1"), new[] { "k1" }),
                    new DictionaryRule(new CategoryNode("Cat2"), new[] { "k2" })
                });

            mockRuleRepo.Setup(r => r.GetAllExecutionRulesAsync())
                .ReturnsAsync(new List<ExecutionRule>
                {
                    new ExecutionRule("Rule1", new RuleNode(LogicalOperator.And), new List<RuleAction> { new RuleAction(ActionType.MarkAsRead, string.Empty) })
                });

            mockShadowService.Setup(s => s.IsAutoWriteEnabledAsync())
                .ReturnsAsync(true);

            var viewModel = new StatusBarViewModel(mockCatRepo.Object, mockRuleRepo.Object, mockShadowService.Object);

            // Act
            await viewModel.InitializeAsync();

            // Assert
            Assert.Equal(3, viewModel.TotalCategoriesCount);
            Assert.Equal(2, viewModel.TotalDictionaryRulesCount);
            Assert.Equal(1, viewModel.TotalExecutionRulesCount);
            Assert.True(viewModel.IsAutoWriteEnabled);
        }

        [Fact]
