            var mockShadowService = new Mock<IShadowModeService>();

            mockCatRepo.Setup(r => r.GetAllAsync(false)).ReturnsAsync(new List<CategoryNode>());
            mockRuleRepo.Setup(r => r.GetAllDictionaryRulesAsync()).ReturnsAsync(new List<DictionaryRule>());
            mockRuleRepo.Setup(r => r.GetAllExecutionRulesAsync()).ReturnsAsync(new List<ExecutionRule>());
            mockShadowService.Setup(s => s.IsAutoWriteEnabledAsync()).ReturnsAsync(false);

            var viewModel = new StatusBarViewModel(mockCatRepo.Object, mockRuleRepo.Object, mockShadowService.Object);
            await viewModel.InitializeAsync();

            Assert.Equal(0, viewModel.TotalCategoriesCount);
